/**
 * Stylesheet imports resolve to the raw CSS text, not to a side effect:
 * esbuild inlines them with `--loader:.css=text`, Vite resolves `?inline` to the
 * stylesheet text, and Vitest returns the content through `test.css: true`.
 */

declare module '*.css?inline' {
  const css: string;
  export default css;
}

declare module '*.css' {
  const css: string;
  export default css;
}

/* Hooks: --x-button-height | --x-button-radius | --x-button-font-size.
   Colours come only from @x/tokens, each with a fallback. */

:host {
  display: inline-block;
  vertical-align: middle;
  color-scheme: light dark;
}

:host([data-theme='dark']) {
  color-scheme: dark;
}

:host([data-theme='light']) {
  color-scheme: light;
}

.base {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.375rem;
  box-sizing: border-box;
  height: var(--x-button-height, 2.25rem);
  padding: 0 1rem;
  border: 1px solid var(--x-color-border-1, #d4d4d8);
  border-radius: var(--x-button-radius, 0.5rem);
  background: var(--x-color-bg-1, #ffffff);
  color: var(--x-color-fg-1, #18181b);
  font-family: inherit;
  font-size: var(--x-button-font-size, 0.875rem);
  font-weight: 500;
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
  user-select: none;
  appearance: none;
  -webkit-appearance: none;
}

.base:hover:not(:disabled) {
  filter: brightness(0.96);
}

.base:focus-visible {
  outline: 2px solid var(--x-color-accent-9, #2563eb);
  outline-offset: 2px;
}

.base:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.base[aria-busy='true'] {
  cursor: progress;
}

:host([size='sm']) .base {
  height: var(--x-button-height, 2rem);
  padding: 0 0.75rem;
  border-radius: var(--x-button-radius, 0.375rem);
  font-size: var(--x-button-font-size, 0.8125rem);
}

:host([size='lg']) .base {
  height: var(--x-button-height, 2.75rem);
  padding: 0 1.25rem;
  border-radius: var(--x-button-radius, 0.625rem);
  font-size: var(--x-button-font-size, 1rem);
}

:host([variant='primary']) .base {
  border-color: var(--x-color-accent-9, #2563eb);
  background: var(--x-color-accent-9, #2563eb);
  color: var(--x-color-bg-1, #ffffff);
}

:host([variant='danger']) .base {
  border-color: var(--x-color-danger-9, #dc2626);
  background: var(--x-color-danger-9, #dc2626);
  color: var(--x-color-bg-1, #ffffff);
}

:host([variant='ghost']) .base {
  border-color: transparent;
  background: transparent;
  color: var(--x-color-fg-1, #18181b);
}

/* Guards against page-level preflight (e.g. Tailwind v4) leaking into the host. */
:host {
  box-sizing: border-box;
  border: 0 solid;
  margin: 0;
  line-height: 1.5;
}

import resetStyles from './reset.css?inline';

/** Values allowed for attribute-backed properties. */
export type Primitive = string | number | boolean;

/** Defaults for attribute-backed properties; keys define the public API. */
export type Defaults = Record<string, Primitive>;

/** `my-attr` -> `myAttr`, so an attribute can drive the camelCase property. */
function toCamelCase(name: string): string {
  return name.replace(/-([a-z0-9])/g, (_, char: string) => char.toUpperCase());
}

/** `myAttr` -> `my-attr`, so a property can reflect to the attribute. */
function toKebabCase(name: string): string {
  return name.replace(/[A-Z]/g, (char) => `-${char.toLowerCase()}`);
}

/**
 * Dependency-free base class for every `x-*` custom element.
 *
 * Contract:
 * - Constructor only touches `this` (`attachShadow`, local fields, accessors):
 *   it never reads `document`, `window`, storage or the network, so importing a
 *   component stays safe under SSR and inside workers.
 * - `static defaults` declares the attribute-backed API. Property accessors are
 *   generated from it and reflect back to attributes, so `el.variant` and
 *   `variant="primary"` can never disagree; attributes stay the source of truth.
 * - Markup comes from `render()` as an HTML string and is written straight into
 *   the shadow root, including `static styles` plus the shared reset.
 * - Listeners belong on the shadow root (event delegation), because re-rendering
 *   replaces the inner markup.
 */
export abstract class XElement extends HTMLElement {
  /** Shadow-DOM stylesheet source for this element. */
  static styles: string = '';

  /** Attribute-backed properties and their defaults. */
  static defaults: Defaults = {};

  /** Attributes the browser reports to `attributeChangedCallback`. */
  static get observedAttributes(): string[] {
    return Object.keys(this.defaults).map(toKebabCase);
  }

  #defaults: Defaults = {};
  #values: Record<string, Primitive> = {};
  #rendered = false;
  #reflecting = false;
  #fallbackStyle: HTMLStyleElement | null = null;

  constructor() {
    super();
    const ctor = this.constructor as typeof XElement;
    const root = this.attachShadow({ mode: 'open' });

    this.#defaults = ctor.defaults;
    this.#values = { ...ctor.defaults };
    this.#adoptStyles(root, `${resetStyles}\n${ctor.styles}`);

    for (const [key, fallback] of Object.entries(ctor.defaults)) {
      const type = typeof fallback;
      Object.defineProperty(this, key, {
        configurable: true,
        enumerable: true,
        get: () => this.#values[key],
        set: (next: Primitive) => this.#assign(key, next, type),
      });
    }
  }

  connectedCallback(): void {
    if (this.#rendered) return;
    this.#rendered = true;
    this.requestUpdate();
  }

  /** Re-renders the shadow root from `render()`. */
  requestUpdate(): void {
    const root = this.shadowRoot;
    if (!root || !this.#rendered) return;
    root.innerHTML = this.render();
    if (this.#fallbackStyle && !this.#fallbackStyle.isConnected) root.prepend(this.#fallbackStyle);
    this.afterRender();
  }

  /** Returns the shadow-DOM markup; called on connect and after every change. */
  protected abstract render(): string;

  /** Hook for state markup cannot express (e.g. `.disabled` on a child node). */
  protected afterRender(): void {}

  /** Dispatches a bubbling, composed `CustomEvent`. */
  emit<T>(name: string, detail?: T): boolean {
    return this.dispatchEvent(new CustomEvent<T>(name, { bubbles: true, composed: true, detail }));
  }

  attributeChangedCallback(name: string, oldValue: string | null, value: string | null): void {
    if (oldValue === value) return;
    const key = toCamelCase(name);
    if (!(key in this.#defaults)) return;
    this.#values[key] = this.#coerce(key, value); // attribute -> camelCase property
    if (this.#rendered && !this.#reflecting) this.requestUpdate();
  }

  #assign(key: string, next: Primitive, type: string): void {
    const value = type === 'boolean' ? Boolean(next) : type === 'number' ? Number(next) : String(next);
    if (Object.is(this.#values[key], value)) return;
    this.#values[key] = value;
    this.#reflect(key, value);
  }

  #reflect(key: string, value: Primitive): void {
    const attribute = toKebabCase(key);
    this.#reflecting = true;
    try {
      if (typeof value === 'boolean') this.toggleAttribute(attribute, value);
      else if (value === this.#defaults[key]) this.removeAttribute(attribute);
      else this.setAttribute(attribute, String(value));
    } finally {
      this.#reflecting = false;
    }
    if (this.#rendered) this.requestUpdate();
  }

  #coerce(key: string, value: string | null): Primitive {
    const fallback = this.#defaults[key];
    if (typeof fallback === 'boolean') return value !== null;
    if (value === null) return fallback;
    if (typeof fallback === 'number') return Number.isNaN(Number(value)) ? fallback : Number(value);
    return value;
  }

  #adoptStyles(root: ShadowRoot, text: string): void {
    if (!text.trim()) return;
    try {
      const sheet = new CSSStyleSheet();
      sheet.replaceSync(text);
      root.adoptedStyleSheets = [sheet];
    } catch {
      if (typeof document === 'undefined') return;
      const style = document.createElement('style');
      style.textContent = text;
      root.prepend(style);
      this.#fallbackStyle = style;
    }
  }
}

import buttonStyles from './x-button.css?inline';
import { XElement } from '../internal/base';

/** Visual intents of `<x-button>`. */
export type XButtonVariant = 'default' | 'primary' | 'danger' | 'ghost';
/** Control sizes of `<x-button>`. */
export type XButtonSize = 'sm' | 'md' | 'lg';
/** Native button types forwarded by `<x-button>`. */
export type XButtonType = 'button' | 'submit' | 'reset';

const VARIANTS: readonly XButtonVariant[] = ['default', 'primary', 'danger', 'ghost'];
const SIZES: readonly XButtonSize[] = ['sm', 'md', 'lg'];
const TYPES: readonly XButtonType[] = ['button', 'submit', 'reset'];

function oneOf<T extends string>(allowed: readonly T[], value: string, fallback: T): T {
  return (allowed as readonly string[]).includes(value) ? (value as T) : fallback;
}

/**
 * `<x-button>` — an action element backed by a real native `<button>` inside
 * the shadow root, so focus, keyboard activation and accessibility come from
 * the platform. Note: `type="submit"` does not submit an outer form (Shadow
 * DOM limitation).
 *
 * The default slot holds the label. `disabled` and `loading` both block the
 * native button and swallow clicks; while loading the internal button also
 * carries `aria-busy="true"`.
 *
 * @attr {('default'|'primary'|'danger'|'ghost')} variant - Visual intent. Default: "default".
 * @attr {('sm'|'md'|'lg')} size - Control size. Default: "md".
 * @attr {boolean} disabled - Disables the native button and blocks `x-button-click`.
 * @attr {boolean} loading - Marks the button busy with `aria-busy="true"` and blocks clicks.
 * @attr {('button'|'submit'|'reset')} type - Native button type. Default: "button".
 * @slot - Default slot: the button label (text, icon, or both).
 * @cssprop --x-button-height - Control height; defaults to 2.25rem (2rem sm, 2.75rem lg).
 * @cssprop --x-button-radius - Corner radius; defaults to 0.5rem (0.375rem sm, 0.625rem lg).
 * @cssprop --x-button-font-size - Label font size; defaults to 0.875rem (0.8125rem sm, 1rem lg).
 * @csspart base - The internal native `<button>` element.
 * @fires x-button-click - Fired when the user activates the button; `detail.originalEvent` is the native MouseEvent.
 */
export class XButton extends XElement {
  static override styles: string = buttonStyles;

  static override defaults = {
    variant: 'default',
    size: 'md',
    disabled: false,
    loading: false,
    type: 'button',
  };

  declare variant: XButtonVariant;
  declare size: XButtonSize;
  declare disabled: boolean;
  declare loading: boolean;
  declare type: XButtonType;

  constructor() {
    super();
    // Delegation on the shadow root survives the innerHTML re-render.
    this.shadowRoot!.addEventListener('click', this.#onClick);
  }

  protected render(): string {
    const type = oneOf(TYPES, this.type, 'button');
    const blocked = this.disabled || this.loading ? ' disabled' : '';
    const busy = this.loading ? ' aria-busy="true"' : '';
    return `<button class="base" part="base" type="${type}"${blocked}${busy}><slot></slot></button>`;
  }

  protected override afterRender(): void {
    const button = this.#button;
    if (!button) return;
    button.disabled = this.disabled || this.loading;
    if (this.loading) button.setAttribute('aria-busy', 'true');
    else button.removeAttribute('aria-busy');
  }

  #onClick = (event: Event): void => {
    if (this.disabled || this.loading) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    this.emit('x-button-click', { originalEvent: event as MouseEvent });
  };

  get #button(): HTMLButtonElement | null {
    return this.shadowRoot?.querySelector('button') ?? null;
  }
}

export { VARIANTS, SIZES, TYPES };
